#!/usr/bin/env bash
# Builds SDKs that have no prebuilt under 100 MiB. Idempotent. Run through scripts/lowprio.sh.
cd "$(dirname "$0")/.." && source scripts/env.sh
J=4; B=third_party/_build; mkdir -p $B logs
run(){ n=$1; shift; echo "[$(date +%T)] start $n"; if "$@" > logs/build_$n.log 2>&1; then echo "[$(date +%T)] ok $n"; else echo "[$(date +%T)] FAIL $n"; fi; }
tflite_c(){ cmake -G Ninja -S third_party/tensorflow/tensorflow/lite/c -B $B/tflite_c -DCMAKE_BUILD_TYPE=Release -DTFLITE_ENABLE_GPU=OFF -DCMAKE_POLICY_VERSION_MINIMUM=3.5 && cmake --build $B/tflite_c -j$J; }
mnn_x64(){ cmake -G Ninja -S third_party/mnn-src -B $B/mnn_x64 -DCMAKE_BUILD_TYPE=Release -DMNN_BUILD_TOOLS=OFF -DMNN_BUILD_SHARED_LIBS=ON -DCMAKE_POLICY_VERSION_MINIMUM=3.5 && cmake --build $B/mnn_x64 -j$J; }
mnn_a64(){ cmake -G Ninja -S third_party/mnn-src -B $B/mnn_a64 -DCMAKE_TOOLCHAIN_FILE=$PWD/scripts/toolchains/zig-aarch64.cmake -DCMAKE_BUILD_TYPE=Release -DMNN_ARM82=OFF -DMNN_BUILD_TOOLS=OFF -DMNN_BUILD_SHARED_LIBS=ON -DCMAKE_POLICY_VERSION_MINIMUM=3.5 && cmake --build $B/mnn_a64 -j$J; }
ncnn_a64(){ d=$(ls -d third_party/ncnn-src/*/ 2>/dev/null | head -1); [ -f third_party/ncnn-src/CMakeLists.txt ] && d=third_party/ncnn-src; cmake -G Ninja -S $d -B $B/ncnn_a64 -DCMAKE_TOOLCHAIN_FILE=$PWD/scripts/toolchains/zig-aarch64.cmake -DCMAKE_BUILD_TYPE=Release -DNCNN_BUILD_TOOLS=OFF -DNCNN_BUILD_EXAMPLES=OFF -DNCNN_BUILD_BENCHMARK=OFF -DNCNN_VULKAN=OFF -DNCNN_SHARED_LIB=OFF -DCMAKE_POLICY_VERSION_MINIMUM=3.5 -DCMAKE_INSTALL_PREFIX=$PWD/$B/ncnn_a64/install && cmake --build $B/ncnn_a64 -j$J --target install; }
tflite_a64(){ cmake -G Ninja -S third_party/tensorflow/tensorflow/lite/c -B $B/tflite_a64 -DCMAKE_TOOLCHAIN_FILE=$PWD/scripts/toolchains/gcc-aarch64.cmake -DXNNPACK_ENABLE_KLEIDIAI=OFF -DCMAKE_C_FLAGS=-Wno-incompatible-pointer-types -DCMAKE_BUILD_TYPE=Release -DTFLITE_ENABLE_GPU=OFF -DCMAKE_POLICY_VERSION_MINIMUM=3.5 -DTFLITE_HOST_TOOLS_DIR=$PWD/$(dirname $(find $B/tflite_c -type f -name flatc -perm -u+x | head -1)) && cmake --build $B/tflite_a64 -j$J; }
ncnn_a32(){ cmake -G Ninja -S third_party/ncnn-src -B $B/ncnn_a32 -DCMAKE_TOOLCHAIN_FILE=$PWD/scripts/toolchains/zig-arm32-musl.cmake -DCMAKE_BUILD_TYPE=Release -DNCNN_BUILD_TOOLS=OFF -DNCNN_BUILD_EXAMPLES=OFF -DNCNN_BUILD_BENCHMARK=OFF -DNCNN_VULKAN=OFF -DNCNN_SHARED_LIB=OFF -DNCNN_OPENMP=OFF -DNCNN_THREADS=OFF -DNCNN_SIMPLEOCV=OFF -DNCNN_ARM82=OFF -DNCNN_RUNTIME_CPU=OFF -DCMAKE_POLICY_VERSION_MINIMUM=3.5 -DCMAKE_INSTALL_PREFIX=$PWD/$B/ncnn_a32/install && cmake --build $B/ncnn_a32 -j$J --target install; }
for t in "${@:-tflite_c mnn_x64 ncnn_a64 mnn_a64 tflite_a64 ncnn_a32}"; do for x in $t; do run $x $x; done; done
